import { Link, NavLink, Outlet } from "react-router";
import { useSession } from "../lib/session";

export const DISCLAIMER =
  "Study aid only. Not clinical guidance. Questions and marking are generated by AI from the publicly available ACTAS Clinical Management Guidelines and may contain errors. Always follow the current CMGs and your service's directions.";

const LINKS = [
  { to: "/", label: "Home", end: true },
  { to: "/quiz", label: "Quiz" },
  { to: "/guidelines", label: "Guidelines" },
  { to: "/medications", label: "Medications" },
  { to: "/settings", label: "Settings" },
];

const navClass = ({ isActive }: { isActive: boolean }) =>
  `flex min-h-12 flex-1 items-center justify-center rounded-sm px-1 text-[0.8rem] font-medium transition-colors sm:min-h-10 sm:flex-none sm:px-3 sm:text-sm ${
    isActive ? "bg-highlight text-on-highlight" : "text-on-surface-variant hover:bg-surface-container"
  }`;

export function Layout() {
  const { me, loading } = useSession();
  return (
    <div className="flex min-h-dvh flex-col pb-[calc(4rem+env(safe-area-inset-bottom))] sm:pb-0">
      <a href="#main" className="sr-only focus:not-sr-only focus:absolute focus:left-2 focus:top-2 focus:z-30 focus:bg-surface-container-lowest focus:p-2">
        Skip to content
      </a>
      <header className="sticky top-0 z-20 bg-surface sm:bg-surface/80 sm:backdrop-blur">
        <div className="mx-auto flex max-w-3xl items-center justify-between gap-3 px-4 py-3">
          <Link to="/" className="font-headline text-xl font-semibold text-primary sm:text-2xl">
            Clinical Recall
          </Link>
          <nav
            aria-label="Main"
            className="fixed inset-x-0 bottom-0 z-20 flex gap-1 bg-surface-container-low px-2 pt-1 pb-[calc(0.25rem+env(safe-area-inset-bottom))] sm:static sm:bg-transparent sm:p-0"
          >
            {LINKS.map((link) => (
              <NavLink key={link.to} to={link.to} end={link.end} className={navClass}>
                {link.label}
              </NavLink>
            ))}
          </nav>
          {!loading && !me?.signedIn && (
            <Link to="/sign-in" className="shrink-0 rounded-sm bg-primary px-3 py-2 text-sm font-semibold text-on-primary">
              Sign in
            </Link>
          )}
        </div>
      </header>
      <main id="main" className="mx-auto w-full max-w-3xl flex-1 px-4 py-6 sm:py-8">
        <Outlet />
      </main>
      <footer className="bg-surface-container-low">
        <div className="mx-auto max-w-3xl space-y-2 px-4 py-6 text-xs leading-relaxed text-on-surface-variant">
          <p>{DISCLAIMER}</p>
          <p>
            Source: ACTAS Clinical Management Guidelines,{" "}
            <a className="underline" href="https://cmg.ambulance.act.gov.au" rel="noopener noreferrer" target="_blank">
              cmg.ambulance.act.gov.au
            </a>
            .
          </p>
        </div>
      </footer>
    </div>
  );
}
